sys_script_include.script:
var DecisionV2Utils = Class.create();
DecisionV2Utils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    //カスタムDecisionテーブルの情報を参照
    getDecisionv23_Results: function() {
        var currentDate = new GlideDate();
        var u_id = this.getParameter('u_id');
        var u_effective_between = currentDate;
        var u_amount = this.getParameter('u_amount');
        try {
            var inputs = {};
            inputs['u_id'] = u_id;
            inputs['u_effective_between'] = u_effective_between;
			if('' != u_amount ){
            inputs['u_amount'] = u_amount;
			}

            var dtAPI = new sn_dt.DecisionTableAPI();
            //カスタムDecisionテーブル(decision_rule_v23)のsys_id
            var response = dtAPI.getDecision('9e75a9090fab72502e576dd530d1b24d', inputs);
            var result_elements = response.result_elements;
            var result = {};
            for (var fieldName in result_elements) {
                // 自身のプロパティのみを対象
                var fieldValue = result_elements[fieldName]; // 項目値を取得

                // 設定値有のResult項目を動態的に取得、オブジェクトに格納して、リターンする
				if (fieldValue !== null && fieldValue !='') {
				result[fieldName] = fieldValue.toString();
				}

            }
            gs.info("result" + JSON.stringify(result));
            return JSON.stringify(result);

            //return JSON.stringify(result_elements);
            /*var result = {
                'u_pattern_1': result_elements.u_pattern_1.getValue(),
                'u_step2_1': result_elements.u_step2_1.getValue(),
                'u_step2_2': result_elements.u_step2_2.getValue(),
            };gs.info("result" + JSON.stringify(result));
            return JSON.stringify(result);*/

            /*var result = {};
            result.u_pattern_1 = result_elements.u_pattern_1.getValue();
            result.u_step2_1 = result_elements.u_step2_1.getValue();
            result.u_step2_2 = result_elements.u_step2_2.getValue();
            return JSON.stringify(result);*/

        } catch (e) {
            gs.error("Couldn't run this script Error: " + e);
        }

    },


    //カスタムDecisionテーブルの情報を参照
    getDecisionv21_Results: function() {
        var currentDate = new GlideDate();
        var u_id = this.getParameter('u_id');
        var u_effective_between = currentDate;
        var u_amount = this.getParameter('u_amount');
        try {
            var inputs = {};
            inputs['u_id'] = u_id;
            inputs['u_effective_between'] = u_effective_between;
            inputs['u_amount'] = u_amount;

            gs.info("input" + JSON.stringify(inputs));
            var dtAPI = new sn_dt.DecisionTableAPI();
            //カスタムDecisionテーブル(decision_rule_v21)のsys_id
            var response = dtAPI.getDecision('d6b5d50d0f2b72502e576dd530d1b28e', inputs);
            gs.info("response" + JSON.stringify(response));
            var result_elements = response.result_elements;
            gs.info("result_elements" + JSON.stringify(result_elements));
            var result = {
                'u_pattern_1': result_elements.u_pattern_1.getValue(),
                'u_step2_1': result_elements.u_step2_1.getValue()
            };
            return JSON.stringify(result);
        } catch (e) {
            gs.error("Couldn't run this script Error: " + e);
        }

    },


    //カスタムDecisionテーブルの情報を参照
    getDecisionv22_Results: function() {
        //var currentDate = new GlideDate();
        var u_id = this.getParameter('u_id');
        gs.info("u_id" + u_id);
        try {
            var inputs = {};
            inputs['u_id'] = u_id;
            gs.info("input" + JSON.stringify(inputs));
            var dtAPI = new sn_dt.DecisionTableAPI();
            //カスタムDecisionテーブルのsys_id
            var response = dtAPI.getDecision('84db37800fa3fa102e576dd530d1b2ce', inputs);
            gs.info("response" + JSON.stringify(response));
            var result_elements = response.result_elements;
            //var response = dtAPI.getAnswers(dtSysId);
            //var response = dtAPI.getAll();
            gs.info("result_elements" + JSON.stringify(result_elements));
            var result = {
                'u_pat_1': result_elements.u_pat_1.getValue(),
                'u_step2_1': result_elements.u_step2_1.getValue()
            };
            return JSON.stringify(result);
        } catch (e) {
            gs.error("Couldn't run this script Error: " + e);
        }

    },


    getRoleResult: function() {
        var gr = new GlideRecord('x_846092_decisio_0_customize_decision');
        gr.addQuery('u_id', 'P00030');
        //gr.addQuery('u_effective_start', "<=", "javascript:gs.endOfToday()");
        gr.addQuery('u_effective_start', "<=", "2026-02-28");
        gr.query();

        if (gr.next()) {
            return JSON.stringify({
                u_result_step2_1: gr.getValue('u_result_step2_1'),
                u_result_pattern_1: gr.getValue('u_result_pattern_1')
            });
        }
        /*var results = [];
        while (gr.next()) {
            results.push({
                u_id: gr.getValue('u_id'),
                u_result_step2_1: gr.getValue('u_result_step2_1'),
                u_result_pattern_1: gr.getValue('u_result_pattern_1')
            });
        }
        gs.info('results' + gr.getValue('u_result_step2_1'));
        return results;*/
    },

    getEmployeeInfo: function() {
        name = this.getParameter("user");
        var gr = new GlideRecord('sys_user');
        gr.addQuery('name', name);
        gr.query();
        if (gr.next()) {
            return JSON.stringify({
                name: gr.getValue('name'),
                email: gr.getValue('email')
            });
        }

    },



    type: 'DecisionV2Utils'
});
